DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('private.base_rules(uuid,jsonb)'::regprocedure) INTO d;d:=replace(d,$s$UNION ALL SELECT x FROM jsonb_array_elements(c->'units') x JOIN tree t ON x->>'parent_id'=t.x->>'id' WHERE coalesce((x->>'active')::boolean,false)$s$,$s$UNION ALL SELECT child.value FROM jsonb_array_elements(c->'units') AS child(value) JOIN tree t ON child.value->>'parent_id'=t.x->>'id' WHERE coalesce((child.value->>'active')::boolean,false)$s$);EXECUTE d;END $patch$;